url_options.body_graphql_query:
query {
  viewer {
    accounts(filter: { accountTag: "__CF_ACCOUNT_ID__" }) {
      rumPageloadEventsAdaptiveGroups(
        filter: {
          date_geq: "${__from:date:YYYY-MM-DD}"
          date_leq: "${__to:date:YYYY-MM-DD}"
          siteTag: "d6c7d92c76644885840437e3fdf3b867"
          bot: 0
        }
        limit: 1000
        orderBy: [date_ASC]
      ) {
        sum { visits }
        dimensions { date }
      }
    }
  }
}

